template:
% 参数由系统自动注入：\def\radius{3} \def\opdist{5} \def\showtangents{1} \def\showradius{1} \def\showline{0} \def\showangle{0} \def\showcentralangle{0} \def\showequalmark{0} \def\showchord{0} \def\labelp{P} \def\labelta{A} \def\labeltb{B}
% 视觉归一化：把图形最宽跨度（圆最左端到外点 P）缩放到 6cm，保证图形视觉大小稳定。
\pgfmathsetmacro{\figscale}{6 / (\radius + \opdist)}
% 装饰尺寸：scale= 会同时缩放坐标和 pt 单位长度，故绝对尺寸除以 figscale 抵消，保证视觉大小恒定。
\pgfmathsetmacro{\dotr}{1.6/\figscale}
% 切点位置：由 OT⊥PT 得 ∠TOP = arccos(radius/opdist)；上切点在正角侧，下切点关于 OP 镜像
\pgfmathsetmacro{\tha}{acos(\radius/\opdist)}
\pgfmathsetmacro{\Tax}{\radius*cos(\tha)}
\pgfmathsetmacro{\Tay}{\radius*sin(\tha)}
% 切线长 PT = sqrt(OP^2 - r^2)
\pgfmathsetmacro{\tlen}{sqrt(\opdist*\opdist - \radius*\radius)}
% 上切点指向 P 的单位向量（下切点镜像用 (vax,-vay)）
\pgfmathsetmacro{\vax}{(\opdist - \Tax)/\tlen}
\pgfmathsetmacro{\vay}{-\Tay/\tlen}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  \coordinate (O) at (0,0);
  \coordinate (P) at (\opdist,0);
  \coordinate (Ta) at (\Tax,\Tay);
  \coordinate (Tb) at (\Tax,-\Tay);
  % 圆
  \draw[thick] (O) circle [radius=\radius];
  % 连心线 OP
  \ifnum\showline>0
    \draw[thick] (O) -- (P);
  \fi
  % 切点半径 OA、OB + 直角记号
  \ifnum\showradius>0
    \draw[thick] (O) -- (Ta);
    \draw[thick] (O) -- (Tb);
    \pgfmathsetmacro{\rs}{min(0.26/\figscale, \radius*0.16, \tlen*0.16)}
    \pgfmathsetmacro{\uax}{-cos(\tha)}
    \pgfmathsetmacro{\uay}{-sin(\tha)}
    \draw[thick] ({\Tax+\rs*\uax},{\Tay+\rs*\uay}) -- ({\Tax+\rs*\uax+\rs*\vax},{\Tay+\rs*\uay+\rs*\vay}) -- ({\Tax+\rs*\vax},{\Tay+\rs*\vay});
    \draw[thick] ({\Tax+\rs*\uax},{-(\Tay+\rs*\uay)}) -- ({\Tax+\rs*\uax+\rs*\vax},{-(\Tay+\rs*\uay+\rs*\vay)}) -- ({\Tax+\rs*\vax},{-(\Tay+\rs*\vay)});
  \fi
  % 切点弦 AB
  \ifnum\showchord>0
    \draw[thick] (Ta) -- (Tb);
  \fi
  % 两条切线 PA、PB
  \ifnum\showtangents>0
    \draw[thick] (P) -- (Ta);
    \draw[thick] (P) -- (Tb);
  \fi
  % 切线长相等记号 PA=PB
  \ifnum\showequalmark>0
    \pgfmathsetmacro{\tk}{min(0.16/\figscale, \tlen*0.1)}
    \pgfmathsetmacro{\mx}{(\Tax+\opdist)/2}
    \draw[thick] ({\mx - \tk*\vay},{\Tay/2 + \tk*\vax}) -- ({\mx + \tk*\vay},{\Tay/2 - \tk*\vax});
    \draw[thick] ({\mx + \tk*\vay},{-\Tay/2 + \tk*\vax}) -- ({\mx - \tk*\vay},{-\Tay/2 - \tk*\vax});
  \fi
  % 两切线夹角 ∠APB 的角弧（在 P 处朝圆心一侧）
  \ifnum\showangle>0
    \pgfmathsetmacro{\pang}{atan2(\Tay,\Tax-\opdist)}
    \pgfmathsetmacro{\pend}{360-\pang}
    \pgfmathsetmacro{\arcp}{min(0.5/\figscale, \tlen*0.28)}
    \draw[thick] ({\opdist+\arcp*cos(\pang)},{\arcp*sin(\pang)}) arc[start angle=\pang, end angle=\pend, radius=\arcp];
  \fi
  % 圆心角 ∠AOB 的角弧（朝 P 一侧）
  \ifnum\showcentralangle>0
    \pgfmathsetmacro{\arco}{min(0.5/\figscale, \radius*0.3)}
    \draw[thick] ({\arco*cos(-\tha)},{\arco*sin(-\tha)}) arc[start angle=-\tha, end angle=\tha, radius=\arco];
  \fi
  % 切点与外点
  \fill (Ta) circle [radius=\dotr pt];
  \node at ({1.14*\Tax},{1.18*\Tay}) {$\labelta$};
  \fill (Tb) circle [radius=\dotr pt];
  \node at ({1.14*\Tax},{-1.18*\Tay}) {$\labeltb$};
  \fill (P) circle [radius=\dotr pt];
  \node[right=3pt] at (P) {$\labelp$};
  % 圆心 O
  \fill (O) circle [radius=\dotr pt];
  \node[below left=2pt] at (O) {$O$};
\end{tikzpicture}
